typedef struct {
  const uint8_t *data;
  size_t size;
  size_t pos;
} BUFFER_READER;

typedef struct {
  uint8_t *data;
  size_t size;
  size_t pos;
} BUFFER_WRITER;

typedef struct {
  // Single-octet identifier encoding the ASN.1 class, type and tag number.
  uint8_t id;
  // A buffer containing the entire DER encoding of the data value including the
  // tag and length, but with the position indicator initialized to the offset
  // of the contents octets.
  BUFFER_READER buf;
} DER_ITEM;

// Represents the number sum([val[i] * 2**(29*i) for i in range(9))
typedef struct {
  uint32_t val[BN_LIMBS];
} bignum256;

// Represents the number sum([val[i] * 2**(29*i) for i in range(18))
typedef struct {
  uint32_t val[2 * BN_LIMBS];
} bignum512;

typedef struct {
  uint64_t length;
  union {
    uint32_t w[16];
    uint8_t  b[64];
  } buf;
  uint32_t h[5];
  uint8_t bufpos;
} ripemd160_state;

typedef struct _SHA1_CTX {
	uint32_t	state[5];
	uint64_t	bitcount;
	uint32_t	buffer[SHA1_BLOCK_LENGTH/sizeof(uint32_t)];
} SHA1_CTX;

typedef struct _SHA256_CTX {
	uint32_t	state[8];
	uint64_t	bitcount;
	uint32_t	buffer[SHA256_BLOCK_LENGTH/sizeof(uint32_t)];
} SHA256_CTX;

typedef struct _SHA512_CTX {
	uint64_t	state[8];
	uint64_t	bitcount[2];
	uint64_t	buffer[SHA512_BLOCK_LENGTH/sizeof(uint64_t)];
} SHA512_CTX;

typedef struct SHA3_CTX
{
	/* 1600 bits algorithm hashing state */
	uint64_t hash[sha3_max_permutation_size];
	/* 1536-bit buffer for leftovers */
	uint64_t message[sha3_max_rate_in_qwords];
	/* count of bytes in the message[] buffer */
	unsigned rest;
	/* size of a message block processed at once */
	unsigned block_size;
} SHA3_CTX;

