import os
import random
from typing import List

# Data type: arbitrary binary data
# Goal: Produce interesting, valid byte buffers for many crypto/hash stubs that
# read FUZZ_PARAM_STR() as an input source. We will generate buffers with
# various lengths and byte patterns commonly triggering different code paths:
# - Empty
# - Short lengths around block sizes (0,1,2,3,7,8,15,16,31,32,63,64,127,128,255,256,511,512,1023,1024)
# - Repeating bytes (0x00, 0xFF), alternating patterns (0xAA,0x55), increasing/decreasing sequences
# - Random-length random data (bounded <= 4096)
# The generator will pack one or more chunks concatenated to encourage
# consumers that slice from FUZZ_PARAM_STR() to find enough data for their caps
# while staying <= 4096 bytes.

MAX_TOTAL = 4096

def _pattern_repeat(byte_val: int, length: int) -> bytes:
    return bytes([byte_val]) * length

def _pattern_alternating(a: int, b: int, length: int) -> bytes:
    return bytes((a if (i % 2 == 0) else b) for i in range(length))

def _pattern_increasing(length: int) -> bytes:
    return bytes((i & 0xFF) for i in range(length))

def _pattern_decreasing(length: int) -> bytes:
    return bytes(((length - 1 - i) & 0xFF) for i in range(length))

def _interesting_lengths(rng: random.Random) -> List[int]:
    base = [0,1,2,3,7,8,15,16,31,32,63,64,95,96,127,128,191,192,255,256,511,512,767,768,1023,1024]
    # pick a few random lengths up to 1024 and a larger up to 2048 to mix in
    base += [rng.randint(0, 1024) for _ in range(3)]
    base += [rng.randint(0, 2048) for _ in range(2)]
    # Ensure positive diversity and clamp to MAX_TOTAL later
    return base

def _make_chunk(rng: random.Random, length: int) -> bytes:
    # Choose pattern family
    choice = rng.randint(0, 7)
    length = max(0, length)
    if length == 0:
        return b""
    if choice == 0:
        return _pattern_repeat(0x00, length)
    if choice == 1:
        return _pattern_repeat(0xFF, length)
    if choice == 2:
        return _pattern_alternating(0xAA, 0x55, length)
    if choice == 3:
        return _pattern_increasing(length)
    if choice == 4:
        return _pattern_decreasing(length)
    if choice == 5:
        # random bytes but with limited alphabet to sometimes compress well
        alphabet = [0x00, 0xFF, 0x20, 0x2E, 0x30, 0x31, 0x41, 0x61]
        return bytes(rng.choice(alphabet) for _ in range(length))
    # choice 6-7: fully random
    return rng.randbytes(length)

def _compose_buffers(rng: random.Random) -> bytes:
    lengths = _interesting_lengths(rng)
    rng.shuffle(lengths)
    # Pick 1..5 chunks to concatenate
    n_chunks = 1 + rng.randint(0, 4)
    out = bytearray()
    for L in lengths:
        if len(out) >= MAX_TOTAL:
            break
        if n_chunks <= 0:
            break
        # Cap chunk to remaining budget and add slight random jitter around L
        jitter = rng.randint(-3, 3)
        want = max(0, L + jitter)
        want = min(want, MAX_TOTAL - len(out))
        chunk = _make_chunk(rng, want)
        out.extend(chunk)
        n_chunks -= 1
    return bytes(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # With some probability, choose a single focused buffer size that many stubs cap to
    # e.g., 32 (digests/keys), 64 (blocks), 128, 256, 512, 1024.
    focus_sizes = [0, 16, 20, 24, 28, 32, 33, 40, 48, 64, 65, 73, 80, 96, 128, 160, 192, 256, 320, 384, 512, 768, 1024]
    if rng.random() < 0.4:
        L = rng.choice(focus_sizes)
        if L == 0:
            return b""
        return _make_chunk(rng, min(L, MAX_TOTAL))
    # Otherwise compose multiple chunks for breadth
    buf = _compose_buffers(rng)
    # Ensure non-empty occasionally to satisfy stubs requiring minimum sizes after slicing
    if len(buf) == 0:
        buf = _make_chunk(rng, rng.randint(1, min(128, MAX_TOTAL)))
    return buf
